INSERT INTO schema_migration(version,filename,checksum,status) VALUES ('004','004_games_ratings_operations.sql','1eccad7988de48cf2a072c4cd9f898b9ae95cdd53f4e95d6a86074ab10cb4063','RUNNING');
CREATE TABLE game_session (
  game_session_id VARCHAR(36) PRIMARY KEY,
  origin VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tournament_match_id VARCHAR(36) NULL,
  status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'WAITING',
  engine_ruleset_version VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  current_move_sequence INT UNSIGNED NOT NULL DEFAULT 0,
  state_snapshot_json JSON NULL,
  snapshot_move_sequence INT UNSIGNED NOT NULL DEFAULT 0,
  snapshot_checksum CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  side_to_move VARCHAR(5) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'WHITE',
  draw_offer_participant_id VARCHAR(36) NULL,
  draw_offered_at DATETIME(3) NULL,
  started_at DATETIME(3) NULL,
  finished_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  lock_version BIGINT UNSIGNED NOT NULL DEFAULT 0,
  UNIQUE KEY uq_session_match (tournament_match_id),
  UNIQUE KEY uq_session_match_scope (game_session_id, tournament_match_id),
  UNIQUE KEY uq_session_origin (game_session_id, origin),
  UNIQUE KEY uq_session_result_scope (game_session_id, origin, tournament_match_id),
  KEY ix_session_recovery (status, started_at),
  CONSTRAINT fk_session_match FOREIGN KEY (tournament_match_id) REFERENCES tournament_match (match_id),
  CONSTRAINT ck_session_origin CHECK ((origin = 'QUICK_PLAY' AND tournament_match_id IS NULL) OR (origin = 'TOURNAMENT' AND tournament_match_id IS NOT NULL)),
  CONSTRAINT ck_session_state CHECK (status IN ('WAITING','IN_PROGRESS','FINALIZED')),
  CONSTRAINT ck_session_started CHECK (status <> 'IN_PROGRESS' OR started_at IS NOT NULL),
  CONSTRAINT ck_session_finished CHECK ((status = 'FINALIZED' AND finished_at IS NOT NULL) OR (status <> 'FINALIZED' AND finished_at IS NULL)),
  CONSTRAINT ck_session_snapshot CHECK (snapshot_move_sequence <= current_move_sequence AND (state_snapshot_json IS NOT NULL OR snapshot_move_sequence = 0)),
  CONSTRAINT ck_session_snapshot_object CHECK (state_snapshot_json IS NULL OR JSON_TYPE(state_snapshot_json) = 'OBJECT'),
  CONSTRAINT ck_session_turn CHECK (side_to_move IN ('WHITE','BLACK')),
  CONSTRAINT ck_session_offer_time CHECK ((draw_offer_participant_id IS NULL AND draw_offered_at IS NULL) OR (draw_offer_participant_id IS NOT NULL AND draw_offered_at IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE game_participant (
  participant_id VARCHAR(36) PRIMARY KEY,
  game_session_id VARCHAR(36) NOT NULL,
  color VARCHAR(5) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id VARCHAR(36) NULL,
  guest_label VARCHAR(64) NULL,
  tournament_match_id VARCHAR(36) NULL,
  entrant_id VARCHAR(36) NULL,
  slot_id VARCHAR(36) NULL,
  first_joined_at DATETIME(3) NULL,
  last_seen_at DATETIME(3) NULL,
  disconnected_at DATETIME(3) NULL,
  reconnect_deadline_at DATETIME(3) NULL,
  disconnect_cause VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NULL,
  presence_epoch VARCHAR(36) NULL,
  connection_generation BIGINT UNSIGNED NOT NULL DEFAULT 0,
  UNIQUE KEY uq_participant_color (game_session_id, color),
  UNIQUE KEY uq_participant_scope (participant_id, game_session_id),
  UNIQUE KEY uq_participant_player_scope (participant_id, game_session_id, player_id, color),
  UNIQUE KEY uq_participant_slot (slot_id),
  KEY ix_participant_games (player_id, game_session_id),
  KEY ix_participant_reconnect (reconnect_deadline_at, participant_id),
  CONSTRAINT fk_participant_session FOREIGN KEY (game_session_id) REFERENCES game_session (game_session_id),
  CONSTRAINT fk_participant_player FOREIGN KEY (player_id) REFERENCES player (player_id),
  CONSTRAINT fk_participant_match FOREIGN KEY (game_session_id, tournament_match_id) REFERENCES game_session (game_session_id, tournament_match_id),
  CONSTRAINT fk_participant_slot FOREIGN KEY (slot_id, tournament_match_id, entrant_id, color) REFERENCES tournament_match_slot (slot_id, match_id, entrant_id, color),
  CONSTRAINT fk_participant_registration FOREIGN KEY (entrant_id, player_id) REFERENCES tournament_player_registration (entrant_id, player_id),
  CONSTRAINT ck_participant_color CHECK (color IN ('WHITE','BLACK')),
  CONSTRAINT ck_participant_identity CHECK ((player_id IS NOT NULL AND guest_label IS NULL) OR (player_id IS NULL AND guest_label IS NOT NULL AND CHAR_LENGTH(guest_label) > 0)),
  CONSTRAINT ck_participant_tournament CHECK ((tournament_match_id IS NULL AND entrant_id IS NULL AND slot_id IS NULL) OR (tournament_match_id IS NOT NULL AND entrant_id IS NOT NULL AND slot_id IS NOT NULL AND player_id IS NOT NULL)),
  CONSTRAINT ck_participant_disconnect CHECK ((disconnected_at IS NULL AND reconnect_deadline_at IS NULL AND disconnect_cause IS NULL) OR (disconnected_at IS NOT NULL AND reconnect_deadline_at IS NOT NULL AND disconnect_cause IS NOT NULL AND reconnect_deadline_at >= disconnected_at AND disconnect_cause IN ('PLAYER_DISCONNECT','SERVER_RESTART','SERVER_SHUTDOWN')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

ALTER TABLE game_session ADD CONSTRAINT fk_session_draw_offer FOREIGN KEY (draw_offer_participant_id, game_session_id) REFERENCES game_participant (participant_id, game_session_id);

CREATE TABLE game_move (
  move_id VARCHAR(36) PRIMARY KEY,
  game_session_id VARCHAR(36) NOT NULL,
  move_sequence INT UNSIGNED NOT NULL,
  participant_id VARCHAR(36) NOT NULL,
  from_square CHAR(2) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  to_square CHAR(2) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  promotion_piece CHAR(1) CHARACTER SET ascii COLLATE ascii_bin NULL,
  accepted_at DATETIME(3) NOT NULL,
  engine_move_payload JSON NULL,
  position_hash_after CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  UNIQUE KEY uq_move_sequence (game_session_id, move_sequence),
  CONSTRAINT fk_move_participant FOREIGN KEY (participant_id, game_session_id) REFERENCES game_participant (participant_id, game_session_id),
  CONSTRAINT ck_move_sequence CHECK (move_sequence > 0),
  CONSTRAINT ck_move_coordinates CHECK (ASCII(SUBSTRING(from_square,1,1)) BETWEEN 97 AND 104 AND ASCII(SUBSTRING(to_square,1,1)) BETWEEN 97 AND 104 AND SUBSTRING(from_square,2,1) IN ('1','2','3','4','5','6','7','8') AND SUBSTRING(to_square,2,1) IN ('1','2','3','4','5','6','7','8') AND from_square <> to_square),
  CONSTRAINT ck_move_promotion CHECK (promotion_piece IS NULL OR promotion_piece IN ('Q','R','B','N'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE game_command_receipt (
  receipt_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  game_session_id VARCHAR(36) NOT NULL,
  participant_id VARCHAR(36) NOT NULL,
  command_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  accepted_move_sequence INT UNSIGNED NULL,
  response_payload JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY uq_command_identity (game_session_id, participant_id, command_id),
  CONSTRAINT fk_command_participant FOREIGN KEY (participant_id, game_session_id) REFERENCES game_participant (participant_id, game_session_id),
  CONSTRAINT fk_command_move FOREIGN KEY (game_session_id, accepted_move_sequence) REFERENCES game_move (game_session_id, move_sequence),
  CONSTRAINT ck_command_response CHECK (JSON_TYPE(response_payload) = 'OBJECT')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE game_result (
  result_id VARCHAR(36) PRIMARY KEY,
  context VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tournament_match_id VARCHAR(36) NULL,
  game_session_id VARCHAR(36) NULL,
  outcome VARCHAR(9) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reason VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  white_points DECIMAL(4,2) NOT NULL,
  black_points DECIMAL(4,2) NOT NULL,
  effective_at DATETIME(3) NOT NULL,
  recorded_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  rules_version VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  UNIQUE KEY uq_result_match (tournament_match_id),
  UNIQUE KEY uq_result_session (game_session_id),
  UNIQUE KEY uq_result_session_identity (result_id, game_session_id),
  CONSTRAINT fk_result_match FOREIGN KEY (tournament_match_id) REFERENCES tournament_match (match_id),
  CONSTRAINT fk_result_session FOREIGN KEY (game_session_id) REFERENCES game_session (game_session_id),
  CONSTRAINT fk_result_origin FOREIGN KEY (game_session_id, context) REFERENCES game_session (game_session_id, origin),
  CONSTRAINT fk_result_session_match FOREIGN KEY (game_session_id, context, tournament_match_id) REFERENCES game_session (game_session_id, origin, tournament_match_id),
  CONSTRAINT ck_result_context CHECK ((context = 'QUICK_PLAY' AND game_session_id IS NOT NULL AND tournament_match_id IS NULL) OR (context = 'TOURNAMENT' AND tournament_match_id IS NOT NULL)),
  CONSTRAINT ck_result_score CHECK ((outcome = 'WHITE_WIN' AND white_points = 1 AND black_points = 0) OR (outcome = 'BLACK_WIN' AND white_points = 0 AND black_points = 1) OR (outcome = 'DRAW' AND white_points = 0.5 AND black_points = 0.5)),
  CONSTRAINT ck_result_reason CHECK (reason IN ('GAME_COMPLETED','RESIGNATION','DRAW_AGREEMENT','MATCH_DEADLINE','SINGLE_NO_SHOW','DOUBLE_NO_SHOW','WITHDRAWAL','RECONNECT_EXPIRED','DOUBLE_DISCONNECT')),
  CONSTRAINT ck_result_draw_reason CHECK (reason NOT IN ('DRAW_AGREEMENT','MATCH_DEADLINE','DOUBLE_NO_SHOW','DOUBLE_DISCONNECT') OR outcome = 'DRAW'),
  CONSTRAINT ck_result_decisive_reason CHECK (reason NOT IN ('RESIGNATION','SINGLE_NO_SHOW','WITHDRAWAL','RECONNECT_EXPIRED') OR outcome IN ('WHITE_WIN','BLACK_WIN')),
  CONSTRAINT ck_result_recorded CHECK (recorded_at >= effective_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE rating_policy (
  policy_version VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
  initial_rating INT NOT NULL,
  k_factor SMALLINT UNSIGNED NOT NULL,
  scale SMALLINT UNSIGNED NOT NULL,
  rounding_method VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  eligibility_parameters JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT ck_rating_policy_parameters CHECK (k_factor > 0 AND scale > 0 AND JSON_TYPE(eligibility_parameters) = 'OBJECT')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE player_rating (
  player_id VARCHAR(36) PRIMARY KEY,
  initial_policy_version VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'platform-elo-1',
  initial_rating INT NOT NULL DEFAULT 1200,
  rating INT NOT NULL DEFAULT 1200,
  rated_games INT UNSIGNED NOT NULL DEFAULT 0,
  wins INT UNSIGNED NOT NULL DEFAULT 0,
  draws INT UNSIGNED NOT NULL DEFAULT 0,
  losses INT UNSIGNED NOT NULL DEFAULT 0,
  initialized_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NULL,
  lock_version BIGINT UNSIGNED NOT NULL DEFAULT 0,
  CONSTRAINT fk_rating_player FOREIGN KEY (player_id) REFERENCES player (player_id),
  CONSTRAINT fk_rating_initial_policy FOREIGN KEY (initial_policy_version) REFERENCES rating_policy (policy_version),
  CONSTRAINT ck_rating_counts CHECK (rated_games = wins + draws + losses)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE rating_settlement (
  settlement_id VARCHAR(36) PRIMARY KEY,
  settlement_sequence BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  result_id VARCHAR(36) NOT NULL,
  game_session_id VARCHAR(36) NULL,
  policy_version VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  rated TINYINT NOT NULL,
  status VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',
  finalized_at DATETIME(3) NULL,
  exclusion_reason VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  move_count INT UNSIGNED NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY uq_settlement_sequence (settlement_sequence),
  UNIQUE KEY uq_settlement_result (result_id),
  UNIQUE KEY uq_settlement_session (settlement_id, game_session_id),
  CONSTRAINT fk_settlement_result FOREIGN KEY (result_id) REFERENCES game_result (result_id),
  CONSTRAINT fk_settlement_result_session FOREIGN KEY (result_id, game_session_id) REFERENCES game_result (result_id, game_session_id),
  CONSTRAINT fk_settlement_policy FOREIGN KEY (policy_version) REFERENCES rating_policy (policy_version),
  CONSTRAINT ck_settlement_eligibility CHECK ((rated = 1 AND exclusion_reason IS NULL AND game_session_id IS NOT NULL AND move_count >= 2) OR (rated = 0 AND exclusion_reason IS NOT NULL)),
  CONSTRAINT ck_settlement_state CHECK ((status = 'PENDING' AND finalized_at IS NULL) OR (status = 'APPLIED' AND finalized_at IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE player_rating_change (
  settlement_id VARCHAR(36) NOT NULL,
  game_session_id VARCHAR(36) NOT NULL,
  participant_id VARCHAR(36) NOT NULL,
  player_id VARCHAR(36) NOT NULL,
  color VARCHAR(5) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  rating_before INT NOT NULL,
  rating_after INT NOT NULL,
  rating_delta INT NOT NULL,
  expected_score DECIMAL(20,18) NOT NULL,
  player_rating_version BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (settlement_id, player_id),
  UNIQUE KEY uq_rating_change_color (settlement_id, color),
  UNIQUE KEY uq_rating_change_version (player_id, player_rating_version),
  CONSTRAINT fk_change_settlement FOREIGN KEY (settlement_id, game_session_id) REFERENCES rating_settlement (settlement_id, game_session_id),
  CONSTRAINT fk_change_participant FOREIGN KEY (participant_id, game_session_id, player_id, color) REFERENCES game_participant (participant_id, game_session_id, player_id, color),
  CONSTRAINT fk_change_rating FOREIGN KEY (player_id) REFERENCES player_rating (player_id),
  CONSTRAINT ck_change_math CHECK (rating_after = rating_before + rating_delta),
  CONSTRAINT ck_change_expected CHECK (expected_score BETWEEN 0 AND 1),
  CONSTRAINT ck_change_version CHECK (player_rating_version > 0),
  CONSTRAINT ck_change_color CHECK (color IN ('WHITE','BLACK'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE tournament_final_standing (
  tournament_id VARCHAR(36) NOT NULL,
  entrant_id VARCHAR(36) NOT NULL,
  final_rank INT UNSIGNED NOT NULL,
  score DECIMAL(8,2) NOT NULL,
  buchholz DECIMAL(12,4) NOT NULL,
  sonneborn_berger DECIMAL(12,4) NOT NULL,
  played_wins INT UNSIGNED NOT NULL,
  tiebreak_policy_version VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  source_competition_version BIGINT UNSIGNED NOT NULL,
  finalized_at DATETIME(3) NOT NULL,
  PRIMARY KEY (tournament_id, entrant_id),
  KEY ix_standing_rank (tournament_id, final_rank, entrant_id),
  CONSTRAINT fk_standing_entrant FOREIGN KEY (entrant_id, tournament_id) REFERENCES tournament_entrant (entrant_id, tournament_id),
  CONSTRAINT ck_standing_values CHECK (final_rank > 0 AND score >= 0 AND buchholz >= 0 AND sonneborn_berger >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scheduled_action (
  action_id VARCHAR(36) PRIMARY KEY,
  action_type VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tournament_id VARCHAR(36) NOT NULL,
  round_id VARCHAR(36) NULL,
  match_id VARCHAR(36) NULL,
  participant_id VARCHAR(36) NULL,
  game_session_id VARCHAR(36) NULL,
  due_at DATETIME(3) NOT NULL,
  generation BIGINT UNSIGNED NOT NULL DEFAULT 0,
  deduplication_key VARCHAR(191) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',
  attempt_count INT UNSIGNED NOT NULL DEFAULT 0,
  lease_owner VARCHAR(128) NULL,
  lease_expires_at DATETIME(3) NULL,
  last_error TEXT NULL,
  completed_at DATETIME(3) NULL,
  UNIQUE KEY uq_action_dedupe (deduplication_key),
  KEY ix_action_due (status, due_at, action_id),
  CONSTRAINT fk_action_tournament FOREIGN KEY (tournament_id) REFERENCES tournament (tournament_id),
  CONSTRAINT fk_action_round FOREIGN KEY (round_id, tournament_id) REFERENCES tournament_round (round_id, tournament_id),
  CONSTRAINT fk_action_match FOREIGN KEY (match_id, tournament_id, round_id) REFERENCES tournament_match (match_id, tournament_id, round_id),
  CONSTRAINT fk_action_session_match FOREIGN KEY (game_session_id, match_id) REFERENCES game_session (game_session_id, tournament_match_id),
  CONSTRAINT fk_action_participant FOREIGN KEY (participant_id, game_session_id) REFERENCES game_participant (participant_id, game_session_id),
  CONSTRAINT ck_action_target CHECK ((action_type = 'REGISTRATION_CLOSE' AND round_id IS NULL AND match_id IS NULL AND participant_id IS NULL AND game_session_id IS NULL) OR (action_type = 'ROUND_START' AND round_id IS NOT NULL AND match_id IS NULL AND participant_id IS NULL AND game_session_id IS NULL) OR (action_type = 'MATCH_DEADLINE' AND round_id IS NOT NULL AND match_id IS NOT NULL AND participant_id IS NULL AND game_session_id IS NULL) OR (action_type = 'RECONNECT_EXPIRY' AND round_id IS NOT NULL AND match_id IS NOT NULL AND participant_id IS NOT NULL AND game_session_id IS NOT NULL)),
  CONSTRAINT ck_action_status CHECK (status IN ('PENDING','CLAIMED','COMPLETED','CANCELLED','FAILED')),
  CONSTRAINT ck_action_lease CHECK ((status = 'CLAIMED' AND lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL) OR (status <> 'CLAIMED' AND lease_owner IS NULL AND lease_expires_at IS NULL)),
  CONSTRAINT ck_action_completion CHECK (status <> 'COMPLETED' OR completed_at IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE outbox_event (
  event_id VARCHAR(36) PRIMARY KEY,
  event_sequence BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  tournament_id VARCHAR(36) NULL,
  game_session_id VARCHAR(36) NULL,
  event_type VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  aggregate_version BIGINT UNSIGNED NOT NULL,
  payload JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  delivery_status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',
  next_attempt_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  attempt_count INT UNSIGNED NOT NULL DEFAULT 0,
  delivered_at DATETIME(3) NULL,
  UNIQUE KEY uq_event_sequence (event_sequence),
  KEY ix_outbox_pending (delivery_status, next_attempt_at, event_sequence),
  CONSTRAINT fk_outbox_tournament FOREIGN KEY (tournament_id) REFERENCES tournament (tournament_id),
  CONSTRAINT fk_outbox_session FOREIGN KEY (game_session_id) REFERENCES game_session (game_session_id),
  CONSTRAINT ck_outbox_status CHECK (delivery_status IN ('PENDING','DELIVERED','FAILED')),
  CONSTRAINT ck_outbox_target CHECK (tournament_id IS NOT NULL OR game_session_id IS NOT NULL),
  CONSTRAINT ck_outbox_payload CHECK (JSON_TYPE(payload) = 'OBJECT'),
  CONSTRAINT ck_outbox_delivered CHECK ((delivery_status = 'DELIVERED' AND delivered_at IS NOT NULL) OR (delivery_status <> 'DELIVERED' AND delivered_at IS NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

